import { useId } from "react"
import { Field, FieldLabel } from "@/components/ui/field"
import { Select, SelectContent, SelectGroup, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"

/** A model to offer, with the thinking levels it supports and the one the agent starts it with. */
export type AgentModelChoice = {
  id: string
  label: string
  thinkingLevels: string[]
  thinking: string
  disabled?: boolean
}

function Choice({ label, value, options, onChange, disabled }: {
  label: string
  value: string
  options: { value: string; label: string; disabled?: boolean }[]
  onChange: (value: string) => void
  disabled: boolean
}) {
  const id = useId()
  return (
    <Field data-disabled={disabled}>
      <FieldLabel htmlFor={id}>{label}</FieldLabel>
      <Select value={value} onValueChange={(next) => next !== null && onChange(next)} disabled={disabled} items={options}>
        <SelectTrigger id={id} className="w-full"><SelectValue /></SelectTrigger>
        <SelectContent>
          <SelectGroup>
            {options.map((option) => (
              <SelectItem key={option.value} value={option.value} disabled={option.disabled}>{option.label}</SelectItem>
            ))}
          </SelectGroup>
        </SelectContent>
      </Select>
    </Field>
  )
}

/**
 * Model and thinking level, side by side. The level the agent starts a model with is marked default. Switching
 * models keeps a level the person picked, when the new model supports it, else takes the new
 * model's own.
 */
export function AgentModelFields({ models, model, thinking, onChange, disabled = false }: {
  models: AgentModelChoice[]
  model: string
  thinking: string
  onChange: (model: string, thinking: string) => void
  disabled?: boolean
}) {
  const current = models.find((choice) => choice.id === model)
  const levels = current?.thinkingLevels ?? [thinking]
  return (
    <div className="grid grid-cols-2 gap-3">
      <Choice
        label="Model"
        value={model}
        disabled={disabled}
        options={models.map((choice) => ({ value: choice.id, label: choice.label, disabled: choice.disabled }))}
        onChange={(next) => {
          const choice = models.find((candidate) => candidate.id === next)
          const picked = thinking !== current?.thinking && choice?.thinkingLevels.includes(thinking)
          if (choice) onChange(next, picked ? thinking : choice.thinking)
        }}
      />
      <Choice
        label="Thinking"
        value={thinking}
        disabled={disabled}
        options={levels.map((level) => ({
          value: level,
          label: level === current?.thinking ? `${level} (default)` : level,
        }))}
        onChange={(next) => onChange(model, next)}
      />
    </div>
  )
}

// Types only, so a server can import this file without the UI.
import type { AgentSource, AgentTool } from "./agent-panel"

type Status = AgentTool["status"]
type Args = Record<string, unknown>

/** How a step reads: "Searching for “x”" while it runs, "Searched for “x”" when done, "Failed to search for “x”". */
export type PiStep = {
  verbs: Record<Status, string>
  /** The full call, shown when the step opens since the title may cut it short. */
  input?: (args: Args) => string | undefined
  /** The title's end; the first line of `input` when left out. */
  subject?: (args: Args) => string | undefined
  /** Web pages the step searched or read, from its arguments or its output. */
  sources?: (args: Args, output?: string) => AgentSource[] | undefined
}

/** The http(s) links in a tool's output, once each. */
function sourcesIn(text: string): AgentSource[] {
  const urls = text.match(/https?:\/\/[^\s"'<>()[\]]+/g) ?? []
  return [...new Set(urls.map((url) => url.replace(/[.,;:!?]+$/, "")))]
    .filter((url) => URL.canParse(url))
    .map((url) => ({ url }))
}

const firstLine = (value: string | undefined) => value?.split("\n")[0]
const more = (count: number) => (count > 1 ? ` and ${count - 1} more` : "")
const text = (key: string) => (args: Args) => (typeof args[key] === "string" ? args[key] : undefined)
const queriesOf = ({ query, queries }: Args) =>
  [queries ?? query].flat().filter((value): value is string => typeof value === "string")
const pagesOf = ({ url, urls }: Args) =>
  [url, urls].flat().filter((page): page is string => typeof page === "string" && URL.canParse(page))
const lines = (values: string[]) => (values.length ? values.join("\n") : undefined)
const run = { running: "Running", complete: "Ran", error: "Failed to run" }

/** Pi's built-in tools and pi-web-access's web tools. Hosts spread this into a table with their own tools. */
export const piSteps: Record<string, PiStep> = {
  bash: { verbs: run, input: text("command") },
  read: { verbs: { running: "Reading", complete: "Read", error: "Failed to read" }, input: text("path") },
  edit: { verbs: { running: "Editing", complete: "Edited", error: "Failed to edit" }, input: text("path") },
  write: { verbs: { running: "Writing", complete: "Wrote", error: "Failed to write" }, input: text("path") },
  grep: { verbs: { running: "Searching for", complete: "Searched for", error: "Failed to search for" }, input: text("pattern") },
  find: { verbs: { running: "Finding", complete: "Found", error: "Failed to find" }, input: text("pattern") },
  ls: { verbs: { running: "Listing", complete: "Listed", error: "Failed to list" }, input: text("path") },
  ask_user: {
    verbs: { running: "Asking", complete: "Asked", error: "Failed to ask" },
    subject: (args) => (typeof args.question === "string" ? args.question : "how to continue"),
  },
  web_search: {
    verbs: { running: "Searching", complete: "Searched", error: "Failed to search" },
    input: (args) => lines(queriesOf(args)),
    subject: (args) => {
      const all = queriesOf(args)
      return all.length ? `for “${all[0]}”${more(all.length)}` : "the web"
    },
    // Results arrive as text with their links.
    sources: (_args, output) => (output ? sourcesIn(output) : undefined),
  },
  fetch_content: {
    verbs: { running: "Reading", complete: "Read", error: "Failed to read" },
    input: (args) => lines(pagesOf(args)),
    subject: (args) => {
      const pages = pagesOf(args)
      return pages.length ? `${new URL(pages[0]).hostname}${more(pages.length)}` : "a page"
    },
    // Known from the call, so the sites show while the pages load.
    sources: (args) => pagesOf(args).map((url) => ({ url })),
  },
}

/** The title, input and sources of one tool call; tools missing from `steps` read "Running <name>" and show their arguments. */
export function piStep(
  call: { name: string; arguments: Args },
  status: Status,
  output?: string,
  steps: Record<string, PiStep> = piSteps,
): Pick<AgentTool, "label" | "input" | "sources"> {
  const step = steps[call.name]
  if (!step) return { label: `${run[status]} ${call.name}`, input: JSON.stringify(call.arguments, null, 2) }
  const input = step.input?.(call.arguments)
  const subject = step.subject ? step.subject(call.arguments) : firstLine(input)
  return {
    label: `${step.verbs[status]} ${subject ?? ""}`.trim(),
    input,
    sources: step.sources?.(call.arguments, output),
  }
}

import { useState } from "react"
import { ChevronDown } from "lucide-react"
import { Button } from "@/components/ui/button"
import { ButtonGroup } from "@/components/ui/button-group"
import { Checkbox } from "@/components/ui/checkbox"
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from "@/components/ui/dropdown-menu"
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/soleone/tooltip/tooltip"
import type { AgentQuestion } from "./ask-user"

const isText = (value: unknown): value is string => typeof value === "string" && value.length > 0
const labelled = (value: unknown): value is { label: string; description?: unknown } =>
  typeof value === "object" && value !== null && "label" in value && isText(value.label)

/** The question in an `ask_user` call, which comes from the model and so may be malformed. */
export function questionOf(data: unknown): AgentQuestion | undefined {
  if (typeof data !== "object" || data === null || !("options" in data) || !Array.isArray(data.options)) return undefined
  const options = data.options.filter(labelled).map(({ label, description }) => ({
    label, description: isText(description) ? description : undefined,
  }))
  if (options.length === 0) return undefined
  const extras = "extras" in data && Array.isArray(data.extras) ? data.extras.filter(labelled) : []
  return {
    question: "question" in data && isText(data.question) ? data.question : undefined,
    options,
    extras: extras.map(({ label }) => ({ label })),
  }
}

/** Short options sit side by side; more or longer ones fold behind the default's menu. */
const fitsInline = ({ options }: AgentQuestion) =>
  options.length === 1 || (options.length <= 3 && options.every((option) => option.label.length <= 20))

/** One click on an option sends it, with the ticked extras. Locked once answered. */
export function QuestionCard({ question, locked, onAnswer }: {
  question: AgentQuestion
  locked: boolean
  onAnswer: (text: string) => void
}) {
  const [ticked, setTicked] = useState<string[]>([])
  const [first, ...rest] = question.options
  const answer = (option: string) => {
    const extras = question.extras?.map((extra) => extra.label).filter((label) => ticked.includes(label)) ?? []
    onAnswer(extras.length ? `${option}\n\nAlso: ${extras.join(", ")}` : option)
  }
  const button = (option: AgentQuestion["options"][number], primary: boolean) => {
    const node = (
      <Button key={option.label} size="sm" variant={primary ? "default" : "outline"} disabled={locked} onClick={() => answer(option.label)}>
        {option.label}
      </Button>
    )
    if (!option.description) return node
    return (
      <Tooltip key={option.label}>
        <TooltipTrigger render={node} />
        <TooltipContent>{option.description}</TooltipContent>
      </Tooltip>
    )
  }
  return (
    <div role="group" aria-label={question.question ?? "Choose how to continue"} className="flex min-w-0 flex-col gap-3 rounded-lg border p-3">
      {question.question && <p className="text-sm font-medium">{question.question}</p>}
      {question.extras && question.extras.length > 0 && (
        <ul className="flex flex-col gap-2">
          {question.extras.map(({ label }) => (
            <li key={label}>
              <label className="flex items-center gap-2 text-sm">
                <Checkbox
                  checked={ticked.includes(label)}
                  disabled={locked}
                  onCheckedChange={(checked) =>
                    setTicked((current) => checked ? [...current, label] : current.filter((each) => each !== label))
                  }
                />
                {label}
              </label>
            </li>
          ))}
        </ul>
      )}
      {fitsInline(question) ? (
        <div className="flex flex-wrap gap-2">{question.options.map((option, index) => button(option, index === 0))}</div>
      ) : (
        <ButtonGroup className="max-w-full">
          {button(first, true)}
          <DropdownMenu>
            <DropdownMenuTrigger render={<Button size="sm" aria-label="Other answers" disabled={locked} />}>
              <ChevronDown />
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="max-w-72">
              {rest.map((option) => (
                <DropdownMenuItem key={option.label} className="flex-col items-start gap-0.5" onClick={() => answer(option.label)}>
                  {option.label}
                  {option.description && <span className="text-xs text-muted-foreground">{option.description}</span>}
                </DropdownMenuItem>
              ))}
            </DropdownMenuContent>
          </DropdownMenu>
        </ButtonGroup>
      )}
    </div>
  )
}

